import{_ as e,o,c as s,a2 as n}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Sintaxis de búsqueda","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/search-syntax.md","filePath":"es-ES/user-guide/search-syntax.md","lastUpdated":1785251801000}'),d={name:"es-ES/user-guide/search-syntax.md"};function i(t,a,r,c,l,u){return o(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="sintaxis-de-busqueda" tabindex="-1">Sintaxis de búsqueda <a class="header-anchor" href="#sintaxis-de-busqueda" aria-label="Permalink to &quot;Sintaxis de búsqueda&quot;">​</a></h1><p>El cuadro de consulta de SwiftList admite más que escribir texto sin más. Cada operador de abajo se puede combinar con términos difusos normales en la misma consulta.</p><h2 id="coincidencia-difusa-predeterminada" tabindex="-1">Coincidencia difusa (predeterminada) <a class="header-anchor" href="#coincidencia-difusa-predeterminada" aria-label="Permalink to &quot;Coincidencia difusa (predeterminada)&quot;">​</a></h2><p>Escribe cualquier parte de un nombre y SwiftList lo encuentra siempre que los caracteres aparezcan en orden, en cualquier parte del nombre del archivo/carpeta — no necesitas escribir una subcadena contigua:</p><table tabindex="0"><thead><tr><th>Escribes</th><th>Coincide con</th></tr></thead><tbody><tr><td><code>swlst</code></td><td><code>SwiftList.exe</code></td></tr><tr><td><code>report</code></td><td><code>Q3-report-final.docx</code></td></tr></tbody></table><h2 id="varias-palabras" tabindex="-1">Varias palabras <a class="header-anchor" href="#varias-palabras" aria-label="Permalink to &quot;Varias palabras&quot;">​</a></h2><p>Separa las palabras con un espacio. Cada palabra reduce aún más el conjunto de resultados — <strong>no</strong> exige que las palabras aparezcan en el mismo orden en que las escribiste:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report final</span></span></code></pre></div><p>coincide igual de bien con <code>final-Q3-report.docx</code> que con <code>Q3-report-final.docx</code>.</p><h2 id="sensibilidad-a-mayusculas" tabindex="-1">Sensibilidad a mayúsculas <a class="header-anchor" href="#sensibilidad-a-mayusculas" aria-label="Permalink to &quot;Sensibilidad a mayúsculas&quot;">​</a></h2><ul><li>Una consulta <strong>totalmente en minúsculas</strong> no distingue mayúsculas de minúsculas: <code>myfile</code> coincide con <code>MyFile</code>, <code>MYFILE</code>, etc.</li><li>Una consulta con <strong>alguna letra mayúscula</strong> pasa a distinguir mayúsculas de minúsculas para ese término: <code>MyFile</code> solo coincide con <code>MyFile</code>, no con <code>myfile</code>.</li></ul><h2 id="operadores" tabindex="-1">Operadores <a class="header-anchor" href="#operadores" aria-label="Permalink to &quot;Operadores&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prefijo/Sufijo</th><th>Ejemplo</th><th>Efecto</th></tr></thead><tbody><tr><td><em>(ninguno)</em></td><td><code>report</code></td><td>Coincidencia difusa en cualquier parte del nombre (predeterminado).</td></tr><tr><td><code>!</code></td><td><code>!temp</code></td><td><strong>Excluir</strong> resultados cuyo nombre contenga la subcadena exacta <code>temp</code> (esta no es difusa).</td></tr><tr><td><code>&#39;</code></td><td><code>&#39;report</code></td><td>Coincidencia de subcadena <strong>exacta</strong> en lugar de difusa.</td></tr><tr><td><code>&#39;...&#39;</code></td><td><code>&#39;final report&#39;</code></td><td>Coincidencia exacta anclada a límites de palabra (no coincidirá dentro de una palabra más larga).</td></tr><tr><td><code>^</code></td><td><code>^IMG</code></td><td>Coincidencia de <strong>prefijo</strong> — el nombre debe empezar por <code>IMG</code>.</td></tr><tr><td><code>$</code></td><td><code>.pdf$</code></td><td>Coincidencia de <strong>sufijo</strong> — el nombre debe terminar en <code>.pdf</code>.</td></tr><tr><td><code>^...$</code></td><td><code>^readme.md$</code></td><td><strong>Igualdad</strong> — el nombre debe ser exactamente <code>readme.md</code>. Solo cuando ambos envuelven la <em>misma</em> palabra; en palabras distintas siguen siendo filtros independientes de prefijo y sufijo.</td></tr><tr><td><code>|</code></td><td><code>report | summary</code></td><td><strong>OR</strong> — coincide con cualquiera de los dos lados de la barra vertical.</td></tr></tbody></table><p>Puedes combinar estos libremente, por ejemplo <code>^IMG !.png$ 2024</code> encuentra archivos que empiecen por <code>IMG</code>, de 2024, que <em>no</em> sean PNG.</p><p>En una consulta OR, todo término que realmente coincida con un resultado dado se resalta en su nombre — no solo el que coincidió primero — así que <code>report | summary</code> resalta ambas palabras en un resultado cuyo nombre las contenga a las dos.</p><h2 id="pegar-varias-lineas" tabindex="-1">Pegar varias líneas <a class="header-anchor" href="#pegar-varias-lineas" aria-label="Permalink to &quot;Pegar varias líneas&quot;">​</a></h2><p>Pega texto que contenga varias líneas — por ejemplo, nombres de archivo copiados uno por línea desde una hoja de cálculo o un archivo de texto — y SwiftList los convierte automáticamente en una consulta OR en lugar de pegarlos tal cual:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>123</span></span>
<span class="line"><span>456</span></span>
<span class="line"><span>678</span></span></code></pre></div><p>se pega como <code>123 | 456 | 678</code>, coincidiendo con cualquiera de los tres. Las líneas en blanco se omiten. Un pegado normal de una sola línea no se ve afectado.</p><h2 id="segmentar-por-unidad" tabindex="-1">Segmentar por unidad <a class="header-anchor" href="#segmentar-por-unidad" aria-label="Permalink to &quot;Segmentar por unidad&quot;">​</a></h2><p>Empieza la consulta con una letra de unidad seguida de dos puntos para restringir los resultados a esa unidad, y luego sigue escribiendo tu búsqueda con normalidad:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d: report</span></span></code></pre></div><p>busca solo en la unidad <code>D:</code>.</p><h2 id="modo-de-ruta" tabindex="-1">Modo de ruta <a class="header-anchor" href="#modo-de-ruta" aria-label="Permalink to &quot;Modo de ruta&quot;">​</a></h2><p>Si tu consulta contiene un separador de ruta (<code>\\</code> o <code>/</code>), SwiftList cambia al modo de ruta y compara contra rutas completas en lugar de solo nombres — útil para saltar directamente a una carpeta conocida:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>D:\\Projects\\SwiftList</span></span></code></pre></div><p>Un separador final (<code>D:\\Projects\\</code>) busca en el <em>contenido</em> de esa carpeta exacta.</p><h2 id="filtrar-por-nombre-de-carpeta" tabindex="-1">Filtrar por nombre de carpeta <a class="header-anchor" href="#filtrar-por-nombre-de-carpeta" aria-label="Permalink to &quot;Filtrar por nombre de carpeta&quot;">​</a></h2><p>Añade un <code>::&lt;texto&gt;</code> al final de una consulta para exigir además que el propio nombre del resultado o el de una de sus carpetas antecesoras coincida con <code>&lt;texto&gt;</code> (de forma difusa, la misma coincidencia — incluido el pinyin — que en cualquier otro lugar):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1080 ::wallpapers</span></span></code></pre></div><p>encuentra archivos con <code>1080</code> en el nombre que vivan en algún lugar bajo una carpeta que coincida con <code>wallpapers</code>, sin necesidad de saber o escribir la ruta exacta. Combina varios filtros con una coma: <code>report ::2024,:final</code>.</p><h2 id="saltarse-las-reglas-de-exclusion-para-una-busqueda" tabindex="-1">Saltarse las reglas de exclusión para una búsqueda <a class="header-anchor" href="#saltarse-las-reglas-de-exclusion-para-una-busqueda" aria-label="Permalink to &quot;Saltarse las reglas de exclusión para una búsqueda&quot;">​</a></h2><p>Empieza una consulta con <code>*</code> para buscar más allá de tus propias <a href="./settings/index-drives.html#reglas-de-exclusion">reglas de exclusión</a> — <code>ExcludedPaths</code>, globs ignorados y expresiones regulares ignoradas — solo para esa búsqueda, sin cambiar tu configuración:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*node_modules</span></span></code></pre></div><p>El propio <code>*</code> se elimina antes de comparar, así que nunca se trata como parte del texto de búsqueda. Esto solo revela resultados que ya estén indexados; una carpeta que <em>nunca</em> se indexó desde un principio (una carpeta excluida en una unidad de red o WSL) seguirá sin aparecer. Los archivos ocultos/de sistema se siguen filtrando de todos modos — esto solo afecta a tu propia configuración de reglas de exclusión. Escribir solo <code>*</code> sin nada detrás todavía muestra un aviso de &quot;sigue escribiendo para buscar&quot; en lugar de &quot;Sin resultados de búsqueda&quot;, ya que aún no se ha ejecutado ninguna búsqueda de verdad.</p><h2 id="activador-de-tipo-de-resultado" tabindex="-1">Activador de tipo de resultado <a class="header-anchor" href="#activador-de-tipo-de-resultado" aria-label="Permalink to &quot;Activador de tipo de resultado&quot;">​</a></h2><p>Opcional, y desactivado por defecto — tú mismo asignas el carácter. Si has asignado un carácter activador a un tipo de resultado en <strong>Configuración → General → Ventana de búsqueda rápida → Prioridad de tipo de resultado</strong>, escribir ese carácter como lo primero de todo en la ventana rápida muestra solo los resultados de ese tipo — Aplicaciones, Configuración, un Filtro de archivos concreto, los propios elementos de un plugin, o simplemente Archivos — ocultando cualquier otro tipo:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>;vs</span></span></code></pre></div><p>encuentra &quot;Visual Studio&quot; solo entre las Aplicaciones, si <code>;</code> es el activador configurado para ese tipo, sin importar qué otro tipo de resultado hubiera coincidido mejor con el texto. Escribir solo el carácter activador sin nada detrás todavía muestra un aviso que nombra el tipo, en lugar de &quot;Sin resultados de búsqueda&quot;. Historial y Favoritos no se ven afectados en ningún caso — siempre aparecen primero, haya activador o no. No hay ningún activador configurado por defecto; ver <a href="./settings/general.html#ventana-de-busqueda-rapida">Configuración general</a> para configurar uno.</p><h2 id="nombres-de-archivo-en-chino-alias-en-pinyin" tabindex="-1">Nombres de archivo en chino: alias en pinyin <a class="header-anchor" href="#nombres-de-archivo-en-chino-alias-en-pinyin" aria-label="Permalink to &quot;Nombres de archivo en chino: alias en pinyin&quot;">​</a></h2><p>Los nombres de archivo que contienen caracteres chinos se pueden buscar automáticamente por pinyin, sin necesidad de ninguna configuración:</p><ul><li><strong>Pinyin completo</strong>: escribir <code>chongqing</code> coincide con un archivo llamado <code>重庆</code>.</li><li><strong>Iniciales</strong>: escribir <code>cq</code> también coincide con <code>重庆</code> (primera letra de cada sílaba).</li><li>Los <strong>caracteres polifónicos</strong> (caracteres con más de una pronunciación válida) generan alias para cada lectura habitual, así que cualquiera que sea la pronunciación en la que pienses es probable que coincida.</li></ul><p>Esto lo gestiona un plugin de alias incluido — ver <strong>Configuración → Plugins</strong> si alguna vez quieres comprobar que está habilitado.</p><h2 id="favoritos-no-alias-personalizados" tabindex="-1">Favoritos, no alias personalizados <a class="header-anchor" href="#favoritos-no-alias-personalizados" aria-label="Permalink to &quot;Favoritos, no alias personalizados&quot;">​</a></h2><p>SwiftList no tiene un sistema genérico de &quot;define tu propio alias/macro&quot;. Lo más parecido es <a href="./settings/favorites.html">Favoritos</a>: fija una carpeta, archivo o URL bajo un nombre para mostrar personalizado, y se vuelve buscable por ese nombre (mostrado con una marca ★ en los resultados). Si lo que realmente quieres es una palabra clave personalizada que lance un programa, consulta en su lugar <a href="./instant-answers.html#comandos-personalizados">Comandos personalizados</a>.</p>`,45)])])}const b=e(d,[["render",i]]);export{m as __pageData,b as default};
